Section CANSEC1. Context {rc : runConstT}.

(* [comment removed for export] *)
Definition hB_postA (gp tp : word) (FR : bvmap 5 word) (fc : bv 32) (SPV P D : Z) (pl : list Z) (lo : Z) (m : amem)
    : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 r20 r22 t3 t4 t5 t6 : word) (f1 f2 f3 f4 f5 : Z) (m' : amem),
    ms' = MS (mkR (Z_to_bv 64 PC_HB_EXIT_RA) (Z_to_bv 64 SPV) gp tp t0 t1 t2 (Z_to_bv 64 P) (Z_to_bv 64 D)
                  (Z_to_bv 64 (DT_BYTES (hp_mtl (huf_draws pl (zlen pl))))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 f5) (Z_to_bv 64 (hp_mtl (huf_draws pl (zlen pl)))) r20
                  (Z_to_bv 64 1) r22 (Z_to_bv 64 (hp_dbuf (huf_draws pl (zlen pl))))
                  (Z_to_bv 64 f1) (Z_to_bv 64 f2) (Z_to_bv 64 f3) (Z_to_bv 64 f4) t3 t4 t5 t6)
             FR (Z_to_bv 64 AFUZZ_MALLOC_HB) fc None m' (seg_rom bsegs)
    /\ 0 <= f1 <= 1 /\ 0 <= f2 <= 1 /\ 0 <= f3 <= 1 /\ 0 <= f4 <= 1 /\ 0 <= f5 <= 1
    /\ munch [(P + 8, P + 16); (SPV - 32, SPV); (SPV, SPV + 24)] m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo SPV
    /\ prod_atA m' P D (hp_rest (huf_draws pl (zlen pl)))
    /\ rw_cells bsegs m' SPV [C8 (Z_to_bv 64 (hp_streams (huf_draws pl (zlen pl)))); C8 (Z_to_bv 64 ASHOFF);
                              C8 (Z_to_bv 64 (hp_symbols (huf_draws pl (zlen pl))))].

Section PhaseB.
  Hypothesis U32R : prod_u32r_stmtA.
  Hypothesis I32R : prod_i32r_stmtA.
  Variables (RNG : footprint) (gp tp : word) (FR : bvmap 5 word) (fc : bv 32) (SPV P D lo : Z) (pl : list Z).

  Hypothesis SP0 : 0 <= SPV.
  Hypothesis SPH : SPV + 128 < 2^47.
  Hypothesis LOS : lo <= SPV - 32.
  Hypothesis LOC : ATOP + 4096 <= lo.
  Hypothesis SZ26 : zlen pl < 2^26.
  Hypothesis PLB : Forall (fun c => 0 <= c < 256) pl.
  Hypothesis BLKP : ablk P (P + 16).
  Hypothesis P8 : P mod 8 = 0.
  Hypothesis DLOC : (pl = [] /\ D = AHarness_iface.AEMPTY) \/ ablk D (D + zlen pl).
  Hypothesis D8 : D mod 8 = 0.
  Hypothesis DP : D + zlen pl <= P \/ P + 16 <= D.
  Hypothesis RI : rng_aimg RNG.
  Hypothesis RSTK : rng RNG lo (SPV - lo).
  Hypothesis RFRM : rng RNG SPV 128.                     (* [comment removed for export] *)
  Hypothesis RP : rng RNG P 16.
  Hypothesis RPS : rng RNG (shad P) 2.
  Hypothesis RD : rng RNG D (zlen pl).
  Hypothesis RDS : rng RNG (shad D) (nshad (zlen pl)).

  Notation WB := [(P + 8, P + 16); (SPV - 32, SPV); (SPV, SPV + 24)].

  Lemma phaseB_proofA : forall (x5 x6 x7 s0v x11 x12 x13 x14 x15 x16 x17 s2v s3v s5v s6v s7v s8v s9v s10v s11v x28 x29 x30 x31 : word)
      (m : amem) (jsp jsp2 : list byte),
    mem_inv bsegs m -> stk bsegs m lo SPV ->
    prod_atA m P D (zlen pl) -> bytes_at bsegs m D (map (Z_to_bv 8) pl) ->
    rt_got m -> rt_shbase m ->
    unpoisoned m P (P + 16) -> unpoisoned m D (D + zlen pl) ->
    rw_cells bsegs m SPV [CB 8 jsp; C8 (Z_to_bv 64 ASHOFF); CB 8 jsp2] ->
    evtF bsegs RNG (hB_postA gp tp FR fc SPV P D pl lo m)
      (MS (mkR (Z_to_bv 64 PC_HB_ENTRY) (Z_to_bv 64 SPV) gp tp x5 x6 x7 s0v (Z_to_bv 64 D) (Z_to_bv 64 P) x11 x12 x13 x14 x15 x16 x17
               s2v s3v (Z_to_bv 64 (zlen pl)) s5v s6v s7v s8v s9v s10v s11v x28 x29 x30 x31)
          FR (Z_to_bv 64 PC_HB_ENTRY) fc None m (seg_rom bsegs)).
Proof.
intros x5 x6 x7 s0v x11 x12 x13 x14 x15 x16 x17 s2v s3v s5v s6v s7v s8v s9v s10v s11v x28 x29 x30 x31 m jsp jsp2 MI ST PR PL GOT SHB UNP UND JS.
unfold PC_HB_ENTRY.
Local Ltac pw := try change (2^31) with 2147483648; try change (2^32) with 4294967296; try change (2^64) with 18446744073709551616; lia.
change (2^47) with 140737488355328 in SPH. change (2^26) with 67108864 in SZ26.
pose proof ATOP_range as AR. unfold ATOP_MIN, ATOP_MAX in AR.
pose proof (ablk_lin _ _ BLKP) as BLP. pose proof (ablk_disj_band _ _ BLKP) as DBP.
