{ intro Z0. destruct DLOC as [[E1 E2]|DL]; [subst pl; change (zlen (@nil Z)) with 0 in Z0; lia | exact DL]. }
assert (DLO : D + zlen pl <= lo /\ 0 < D).
{ destruct DLOC as [[E1 E2]|DL]; [subst pl; subst D; change (zlen (@nil Z)) with 0; unfold AHarness_iface.AEMPTY; lia|].
  pose proof (ablk_lin _ _ DL). unfold AIMG_HI in *. lia. }
