assert (UNPT : forall m1, munch WB m m1 -> unpoisoned m1 P (P + 16) /\ unpoisoned m1 D (D + zlen pl)).
{ intros m1 MU. unfold KHIGH in KL. split.
  - (eapply unpoisoned_munch; [eassumption| exact MU|]); rewrite !shad_div; unfold ASHOFF; cbn [disjoint_from];
    repeat (split; [Z.div_mod_to_equations; lia|]); exact I.
  - destruct (Z.eq_dec (zlen pl) 0) as [E0|N0].
    + replace (D + zlen pl) with D by lia. apply unpoisoned_nil. pw.
    + pose proof (ablk_lin _ _ (BLKD ltac:(lia))) as LD. pose proof (ablk_disj_band _ _ (BLKD ltac:(lia))) as DBD.
      unfold KLS, AIMG_HI in LD, DBD.
      (eapply unpoisoned_munch; [eassumption| exact MU|]); rewrite !shad_div; unfold ASHOFF; cbn [disjoint_from];
